type AutomationsListRunsParams struct {
	// next_cursor из ответа прошлой страницы; без него — первая (самая свежая) страница. Остальные фильтры — те же, что у первой страницы.
	//
	// Leave it empty for the first page; Next and the auto-paging iterator fill it in.
	Cursor *string
	// Только запуски этого события хука (hev_… из ответа на приём)
	EventID *string
	// Только запуски по событию с этим id у отправителя (поле по id_path хука, Idempotency-Key или X-Event-Id) — найти запуск по своему заказу или платежу
	ExternalID *string
	// Сколько запусков на странице: 1–100, по умолчанию 20
	Limit *int64
	// Только запуски этого сценария (scn_…)
	Scenario *string
}

// ListRuns: Журнал запусков
//
// GET /v1/companies/{co}/automations/runs
//
// It returns one page; call Next on it for the following one, or use ListRunsAll to iterate over every item.
//
// Required permission: company.read.
func (s *AutomationsService) ListRuns(ctx context.Context, params *AutomationsListRunsParams, opts ...Option) (*ListCompanyAutomationsRunsResponse, error) {
	spec := requestSpec{
		method: "GET",
		path:   "/v1/companies/{co}/automations/runs",
		auth:   authKey,
	}
	if params != nil {
		spec.query = url.Values{}
		addQuery(spec.query, "cursor", params.Cursor)
		addQuery(spec.query, "event_id", params.EventID)
		addQuery(spec.query, "external_id", params.ExternalID)
		addQuery(spec.query, "limit", params.Limit)
		addQuery(spec.query, "scenario", params.Scenario)
	}
	out := new(ListCompanyAutomationsRunsResponse)
	if err := s.client.do(ctx, &spec, out, opts); err != nil {
		return nil, err
	}
	out.next = func(ctx context.Context, cursor string) (*ListCompanyAutomationsRunsResponse, error) {
		var p AutomationsListRunsParams
		if params != nil {
			p = *params
		}
		p.Cursor = &cursor
		return s.ListRuns(ctx, &p, opts...)
	}
	return out, nil
}

// ListRunsAll iterates over every item of every page of ListRuns, fetching the next page only when the
// loop needs it. The filters in params and the request options apply to every page. The
// iteration stops at the first error, which is yielded once; a cursor that repeats is
// reported as a *PaginationError instead of looping forever.
func (s *AutomationsService) ListRunsAll(ctx context.Context, params *AutomationsListRunsParams, opts ...Option) iter.Seq2[AutomationRun, error] {
	return autoPage[AutomationRun, *ListCompanyAutomationsRunsResponse](func() (*ListCompanyAutomationsRunsResponse, error) {
		return s.ListRuns(ctx, params, opts...)
	}, func(p *ListCompanyAutomationsRunsResponse) (*ListCompanyAutomationsRunsResponse, error) {
		return p.Next(ctx)
	})
}

